Object.assign(window.TEM8_DICTIONARY, {"overtook":{"collins":{"senses":[{"pos":"","cn":"","en":"Overtook is the past tense of overtake."}]},"media":{"uk":"media/uk/overtook__gb_1.mp3","us":"media/us/overtook__us_1.mp3"}},"oval":{"media":{"uk":"media/uk/oval__gb_1.mp3","us":"media/us/oval__us_1.mp3"},"oxford":{"phon":"ˈəʊvl","pos":"adjective","senses":[{"en":"like an egg in shape","cn":"椭圆形的；卵形的","ex":{"en":"an oval face","cn":"鹅蛋脸"}},{"en":"an oval shape","cn":"椭圆形；卵形","pos":"noun"},{"en":"a ground for Australian Rules football","cn":"澳大利亚式橄榄球球场","lab":"Australian English","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"椭圆形的；卵形的","en":"Oval things have a shape that is like a circle but is wider in one direction than the other.","ex":{"en":"He was a man in his late thirties, with fine, dark hair and a pale oval face.","cn":"他年近四十，头发乌黑亮泽，长着一张苍白的鹅蛋脸。"}}]},"examples":[{"en":"an oval face","cn":"鹅蛋脸"}]},"overseas":{"media":{"uk":"media/uk/overseas__gb_1.mp3","us":"media/us/overseas__us_1.mp3"},"oxford":{"phon":"ˌəʊvəˈsiːz","pos":"adjective","senses":[{"en":"connected with foreign countries, especially those separated from your country by the sea or ocean","cn":"外国的；海外的","ex":{"en":"The firm is expanding into overseas markets.","cn":"该公司正在向海外市场扩张。"}},{"en":"to or in a foreign country, especially those separated from your country by the sea or ocean","cn":"在国外；向海外","ex":{"en":"to live/work/go overseas","cn":"在国外生活／工作；出国"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（在）海外的；（在）国外的","en":"You use overseas to describe things that involve or are in foreign countries, usually across a sea or an ocean.","ex":{"en":"He has returned to South Africa from his long overseas trip.","cn":"他结束了漫长的海外旅行回到南非。"}},{"pos":"ADJ 形容词","cn":"（学生、游客等）来自海外的，来自外国的","en":"An overseas student or visitor comes from a foreign country, usually across a sea or an ocean.","ex":{"en":"Every year nine million overseas visitors come to London.","cn":"每年有900万外国游客来伦敦观光。"}}]},"examples":[{"en":"The product is sold both at home and overseas.","cn":"这个产品行销国内外。"},{"en":"to live/work/go overseas","cn":"在国外生活/工作；出国"}]},"overtime":{"media":{"uk":"media/uk/overtime__gb_1.mp3","us":"media/us/overtime__us_1.mp3"},"oxford":{"phon":"ˈəʊvətaɪm","pos":"noun","senses":[{"en":"time that you spend working at your job after you have worked the normal hours","cn":"加班；加班的时间","lab":"British English","ex":{"en":"to do/work overtime","cn":"加班"}},{"en":"the money somebody earns for doing overtime","cn":"加班费","ex":{"en":"They pay $150 a day plus overtime.","cn":"他们支付每天 150 美元的报酬，外加加班费。"}},{"en":"a set period of time that is added to the end of a sports game, etc., if there is no winner at the end of the normal period","cn":"（体育比赛等的）加时，加时赛","lab":"North American English","ex":{"en":"The game went into overtime.","cn":"比赛进入了加时赛。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"加班；加班时间","en":"Overtime is time that you spend doing your job in addition to your normal working hours.","ex":{"en":"He would work overtime, without pay, to finish a job","cn":"他会为了完成工作无偿加班。"}},{"pos":"PHRASE 短语","cn":"投入全力；热情高涨","en":"If you say that someone is working overtime to do something, you mean that they are using a lot of energy, effort, or enthusiasm trying to do it.","ex":{"en":"We had to battle very hard and our defence worked overtime to keep us in the game","cn":"我们不得不奋力搏杀；为保证我们不被淘汰出局，防守队员拼尽了全力。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（体育比赛中为决胜负而延长的）加时赛","en":"Overtime is an additional period of time that is added to the end of a sports match in which the two teams are level, as a way of allowing one of the teams to win.","ex":{"en":"Denver had won the championship by defeating the Cleveland Browns 23-20 in overtime.","cn":"丹佛队在加时赛中以23比20击败克利夫兰布朗队夺得冠军。"}}]},"examples":[{"en":"They pay $150 a day plus overtime.","cn":"他们支付每天 150 元的报酬，外加加班费。"},{"en":"There was nothing to worry about. It was just her imagination working overtime.","cn":"没什么可担心的。那只是她的想像力太活跃了。"}]},"overshadow":{"oxford":{"phon":"ˌəʊvəˈʃædəʊ","pos":"verb","senses":[{"en":"to make somebody/something seem less important, or successful","cn":"使显得逊色；使黯然失色","ex":{"en":"He had always been overshadowed by his elder sister.","cn":"他与他姐姐相比总是相形见绌。"}},{"en":"to make an event less pleasant than it should be","cn":"使扫兴；使蒙上阴影","ex":{"en":"News of the accident overshadowed the day's events.","cn":"出事的消息给这一天的活动蒙上了阴影。"}},{"en":"to throw a shadow over something","cn":"掩盖；遮蔽","ex":{"en":"The garden is overshadowed by tall trees.","cn":"花园中大树浓荫密布。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"给…蒙上阴影；使扫兴","en":"If an unpleasant event or feeling overshadows something, it makes it less happy or enjoyable.","ex":{"en":"Fears for the President's safety could overshadow his peace-making mission","cn":"对总统安全的担忧可能会给他的调解使命蒙上阴影。"}},{"pos":"VERB 动词","cn":"使黯然失色；使相形见绌；使显得无足轻重","en":"If you are overshadowed by a person or thing, you are less successful, important, or impressive than they are.","ex":{"en":"Hester is overshadowed by her younger and more attractive sister.","cn":"赫斯特在她那年轻而且姿色更胜一筹的妹妹面前黯然失色。"}},{"pos":"VERB 动词","cn":"（楼房、树木、大型建筑物等）遮蔽，遮挡","en":"If one building, tree, or large structure overshadows another, it stands near it, is much taller than it, and casts a shadow over it.","ex":{"en":"He also designed one of the Edinburgh University towers that overshadows George Square","cn":"他还设计了爱丁堡大学一座投影于乔治广场的塔楼。"}}]},"media":{"uk":"media/uk/overshadow__gb_1.mp3","us":"media/us/overshadow__us_1.mp3"},"examples":[{"en":"News of the accident overshadowed the day's events.","cn":"出事的消息给这一天的活动蒙上了阴影。"},{"en":"He had always been overshadowed by his elder sister.","cn":"他与他姐姐相比总是相形见绌。"}]},"overall":{"media":{"img":["media/pic/overalls_dungarees.jpg","media/thumb/overalls.jpg"],"uk":"media/uk/overall__gb_1.mp3","us":"media/us/overall__us_1.mp3"},"oxford":{"phon":"ˌəʊvərˈɔːl","pos":"adjective","senses":[{"en":"including all the things or people that are involved in a particular situation; general","cn":"全面的；综合的；总体的","ex":{"en":"There will be winners in each of three age groups, and one overall winner.","cn":"三个年龄组将各产生一位优胜者，另有一位总优胜者。"}},{"en":"including everything or everyone; in total","cn":"全部；总计","ex":{"en":"The company will invest $1.6m overall in new equipment.","cn":"这个公司将总计投资 160 万美元购置新设备。"},"pos":"adverb"},{"en":"generally; when you consider everything","cn":"一般来说；大致上；总体上","ex":{"en":"Overall, this is a very useful book.","cn":"总的来说，这是一本很有用的书。"},"pos":"adverb"},{"en":"a loose coat worn over other clothes to protect them from dirt, etc.","cn":"外套；罩衣","g":"[countable]","lab":"British English","ex":{"en":"The lab assistant was wearing a white overall.","cn":"实验室助手穿着一件白罩衣。"},"pos":"noun"},{"en":"a loose piece of clothing like a shirt and trousers in one piece, made of heavy cloth and usually worn over other clothing by workers doing dirty work","cn":"工装服；连身工作服","g":"[plural]","lab":"British English","ex":{"en":"The mechanic was wearing a pair of blue overalls.","cn":"机修工穿着一件蓝色工装连衣裤。"},"pos":"noun"},{"en":"a piece of clothing that consists of trousers with an extra piece of cloth covering the chest, held up by narrow pieces of cloth over the shoulders","cn":"工装裤；工装服","g":"[plural]","lab":"both North American English","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"总的；总体的；全面的","en":"You use overall to indicate that you are talking about a situation in general or about the whole of something.","ex":{"en":"...the overall rise in unemployment","cn":"失业率总体的上升"}},{"pos":"N-PLURAL 复数名词","cn":"（上下连身的）工作服，防护服","en":"Overalls consist of a single piece of clothing that combines trousers and a jacket. You wear overalls over your clothes in order to protect them while you are working.","ex":{"en":"...workers in blue overalls.","cn":"穿着蓝色连身工作服的工人"}},{"pos":"N-PLURAL 复数名词","cn":"（吊带）工装裤","en":"Overalls are trousers that are attached to a piece of cloth which covers your chest and which has straps going over your shoulders.","ex":{"en":"An elderly man dressed in faded overalls took the witness stand.","cn":"一位穿着褪色吊带工装裤的老人上了证人席。"}},{"pos":"N-COUNT 可数名词","cn":"（工作时穿的）罩衣","en":"An overall is a piece of clothing shaped like a coat that you wear over your clothes in order to protect them while you are working."}]},"examples":[{"en":"There will be winners in each of three age groups, and one overall winner.","cn":"三个年龄组将各产生一位优胜者，另有一位总优胜者。"},{"en":"The company will invest $1.6m overall in new equipment.","cn":"这个公司将总计投资 160 万元购置新设备。"}]},"override":{"oxford":{"phon":"ˌəʊvəˈraɪd","pos":"verb","senses":[{"en":"to use your authority to reject somebody’s decision, order, etc.","cn":"（以权力）否决，推翻，不理会","ex":{"en":"The chairman overrode the committee's objections and signed the agreement.","cn":"主席不顾委员会的反对，径行签署了协议。"}},{"en":"to be more important than something","cn":"比…更重要；凌驾","ex":{"en":"Considerations of safety override all other concerns.","cn":"对安全的考虑高于一切。"}},{"en":"to interrupt the action of a device that usually works by itself in order to control it yourself","cn":"超控（使自动控制暂时失效，改用手动控制）","ex":{"en":"A special code is needed to override the time lock.","cn":"这定时锁要用特定密码才能打开。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"凌驾于；优先于；比…更重要","en":"If one thing in a situation overrides other things, it is more important than them.","ex":{"en":"The welfare of a child should always override the wishes of its parents","cn":"孩子的幸福安康应该永远比父母的愿望来得更重要。"}},{"pos":"VERB 动词","cn":"（以更大的权力）撤销，推翻，否决","en":"If someone in authority overrides a person or their decisions, they cancel their decisions.","ex":{"en":"The president vetoed the bill, and the Senate failed by a single vote to override his veto","cn":"总统否决了该议案，而参议院以一票之差未能推翻他的否决。"}},{"pos":"N-COUNT 可数名词","cn":"（对决定等的）撤销，推翻，否决","en":"An override is an attempt to cancel someone's decisions by using your authority over them or by gaining more votes than them in an election or contest.","ex":{"en":"The bill now goes to the House where an override vote is expected to fail","cn":"该议案现在提交到众议院，在这里否决投票预计不会获得通过。"}}]},"media":{"uk":"media/uk/override__gb_1.mp3","us":"media/us/override__us_1.mp3"},"examples":[{"en":"The chairman overrode the committee's objections and signed the agreement.","cn":"主席不顾委员会的反对，径行签署了协议。"},{"en":"A special code is needed to override the time lock.","cn":"这定时锁要用特定密码才能打开。"}]},"overnight":{"media":{"uk":"media/uk/overnight__gb_1.mp3","us":"media/us/overnight__us_1.mp3"},"oxford":{"phon":"ˌəʊvəˈnaɪt","pos":"adverb","senses":[{"en":"during or for the night","cn":"在夜间；在晚上","ex":{"en":"We stayed overnight in London after the theatre.","cn":"我们看完戏后在伦敦住了一晚。"}},{"en":"suddenly or quickly","cn":"突然；一夜之间；旋即","ex":{"en":"Don't expect it to improve overnight.","cn":"不要指望这事一下子就改善了。"}},{"en":"happening during the night; for a night","cn":"夜间的；晚上的；只供一夜的","ex":{"en":"an overnight flight","cn":"夜间飞行"},"pos":"adjective"},{"en":"happening suddenly or quickly","cn":"突然的；很快的；一夜之间的","ex":{"en":"The play was an overnight success.","cn":"这部剧作一夜成名。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"在整个夜间；在夜里的某一时刻","en":"If something happens overnight, it happens throughout the night or at some point during the night.","ex":{"en":"The weather remained calm overnight","cn":"整晚都悄然无风。"}},{"pos":"ADV 副词","cn":"突然；一下子；一夜之间","en":"You can say that something happens overnight when it happens very quickly and unexpectedly.","ex":{"en":"The rules are not going to change overnight","cn":"这些规定不会说变就变。"}},{"pos":"ADJ 形容词","cn":"只供一两晚使用的","en":"Overnight bags or clothes are ones that you take when you go and stay somewhere for one or two nights.","ex":{"en":"He realized he'd left his overnight bag at Mary's house.","cn":"他意识到自己把过夜包落在玛丽家了。"}},{"pos":"VERB 动词","cn":"过夜","en":"If you overnight somewhere, you spend the night there.","ex":{"en":"They had told her she would be overnighting in Sydney.","cn":"他们跟她说过她将在悉尼过夜。"}}]},"examples":[{"en":"She took only an overnight bag (= containing the things needed for a night spent away from home).","cn":"她只带了一个外出住宿一晚的用品旅行袋。"},{"en":"We stayed overnight in London after the theatre.","cn":"我们看完戏后在伦敦住了一晚。"}]},"overwork":{"media":{"uk":"media/uk/overwork__gb_1.mp3","us":"media/us/overwork__us_1.mp3"},"oxford":{"phon":"ˌəʊvəˈwɜːk","pos":"verb","senses":[{"en":"to work too hard; to make a person or an animal work too hard","cn":"（使）过度劳累，过分努力","ex":{"en":"You look tired. Have you been overworking?","cn":"你似乎很疲倦，是不是近来劳累过度了？"}},{"en":"the fact of working too hard","cn":"劳累过度；过分辛苦","ex":{"en":"His illness was brought on by money worries and overwork.","cn":"他的病是因操心钱和劳累过度而造成的。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）工作过度；（使）过分劳累","en":"If you overwork or if someone overworks you, you work too hard, and are likely to become very tired or ill.","ex":{"en":"He's overworking and has got a lot on his mind","cn":"他工作太累，而且非常操心。"}}]},"examples":[{"en":"You look tired. Have you been overworking?","cn":"你似乎很疲倦，是不是近来劳累过度了？"},{"en":"His illness was brought on by money worries and overwork.","cn":"他的病是因操心钱和劳累过度而造成的。"}]},"overlaps":{"oxford":{"phon":"ˌəʊvəˈlæp","pos":"verb","senses":[{"en":"if one thing overlaps another, or the two things overlap , part of one thing covers part of the other （","cn":"物体）部分重叠，交叠"},{"en":"to make two or more things overlap","cn":"使部分重叠"}]},"media":{"uk":"media/uk/overlap__gb_1.mp3","us":"media/us/overlap__us_1.mp3"}},"overcome":{"media":{"uk":"media/uk/overcome__gb_1.mp3","us":"media/us/overcome__us_1.mp3"},"oxford":{"phon":"ˌəʊvəˈkʌm","pos":"verb","senses":[{"en":"to succeed in dealing with or controlling a problem that has been preventing you from achieving something","cn":"克服；解决","ex":{"en":"She overcame injury to win the Olympic gold medal.","cn":"她战胜了伤痛，赢得了奥运会金牌。"}},{"en":"to defeat somebody","cn":"战胜","ex":{"en":"In the final game Sweden easily overcame France.","cn":"在决赛中，瑞典队轻松战胜了法国队。"}},{"en":"to affect somebody very strongly","cn":"使受巨大影响；使难以承受","g":"[usually passive]","ex":{"en":"Her parents were overcome with grief at the funeral.","cn":"在葬礼上她的父母悲痛欲绝。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"克服；控制；战胜","en":"If you overcome a problem or a feeling, you successfully deal with it and control it.","ex":{"en":"Molly had fought and overcome her fear of flying","cn":"莫莉已经努力克服了对飞行的恐惧。"}},{"pos":"VERB 动词","cn":"（感情上）受到极大影响，承受不起","en":"If you are overcome by a feeling or event, it is so strong or has such a strong effect that you cannot think clearly.","ex":{"en":"The night before the test I was overcome by fear and despair","cn":"考试前的晚上，恐惧和绝望让我内心无比惊慌。"}},{"pos":"VERB 动词","cn":"（烟、毒气等）熏倒，使受不了","en":"If you are overcome by smoke or a poisonous gas, you become very ill or die from breathing it in.","ex":{"en":"The residents were trying to escape from the fire but were overcome by smoke.","cn":"居民试图逃离火场，却被浓烟熏倒了。"}}]},"examples":[{"en":"The two parties managed to overcome their differences on the issue.","cn":"两个政党设法弥合了在这个问题上的分歧。"},{"en":"In the final game Sweden easily overcame France.","cn":"在决赛中，瑞典队轻松战胜了法国队。"}]},"over":{"media":{"uk":"media/uk/over__gb_1.mp3","us":"media/us/over__us_1.mp3"},"oxford":{"phon":"ˈəʊvə(r)","pos":"preposition","senses":[{"en":"resting on the surface of somebody/something and partly or completely covering them/it","cn":"（部分或全部覆盖）在…上面","ex":{"en":"She put a blanket over the sleeping child.","cn":"她给熟睡的孩子盖上毯子。"}},{"en":"in or to a position higher than but not touching somebody/something; above somebody/something","cn":"悬在…上面；向…上方","ex":{"en":"They held a large umbrella over her.","cn":"他们给她撑起一把大伞。"}},{"en":"from one side of something to the other; across something","cn":"从一边到另一边；穿越","ex":{"en":"a bridge over the river","cn":"横跨河面的桥"}},{"en":"so as to cross something and be on the other side","cn":"到另一边；翻越","ex":{"en":"She climbed over the wall.","cn":"她翻过墙去。"}},{"en":"falling from or down from a place","cn":"从…落下","ex":{"en":"The car had toppled over the cliff.","cn":"汽车从山崖上跌落下去了。"}},{"en":"on the far or opposite side of something","cn":"在…的远端（或对面）","ex":{"en":"He lives over the road.","cn":"他住在马路对面。"}},{"en":"in or on all or most parts of something","cn":"遍及","ex":{"en":"Snow is falling all over the country.","cn":"全国各地都在下雪。"}},{"en":"more than a particular time, amount, cost, etc.","cn":"多于（某时间、数量、花费等）","ex":{"en":"over 3 million copies sold","cn":"售出三百多万册"}},{"en":"used to show that somebody has control or authority","cn":"（表示能控制、有权威）","ex":{"en":"She has only the director over her.","cn":"她的上司只有主任一个。"}},{"en":"during something","cn":"在…期间","ex":{"en":"We'll discuss it over lunch.","cn":"我们将在吃午饭时商量此事。"}},{"en":"past a particular difficult stage or situation","cn":"渡过（困难阶段或局面）","ex":{"en":"We're over the worst of the recession.","cn":"我们已渡过了经济衰退的最艰难时期。"}},{"en":"because of or relating to something; about something","cn":"由于；关于","ex":{"en":"an argument over money","cn":"为了钱的争吵"}},{"en":"using something; by means of something","cn":"利用；通过","ex":{"en":"We heard it over the radio.","cn":"我们从广播中听到的。"}},{"en":"louder than something","cn":"声音大于","ex":{"en":"I couldn't hear what he said over the noise of the traffic.","cn":"交通噪声太大，我听不清他说的话。"}},{"en":"across a street, an open space, etc.","cn":"穿过（街道、开阔的空间等）","ex":{"en":"I stopped and crossed over.","cn":"我停下来，走到对面。"},"pos":"adverb"},{"en":"downwards and away from the correct position standing upright","cn":"（从直立位置）翻倒，倒下","ex":{"en":"Try not to knock that vase over.","cn":"小心别把那个花瓶碰倒了。"},"pos":"adverb"},{"en":"from one side to another side","cn":"从一侧到另一侧；翻转","ex":{"en":"She turned over onto her front.","cn":"她翻过身俯卧着。"},"pos":"adverb"},{"en":"so as to cover somebody/something completely","cn":"完全覆盖（某人或某物）","ex":{"en":"The lake was frozen over.","cn":"湖面完全封冻了。"},"pos":"adverb"},{"en":"above; more","cn":"以上；大于；多于","ex":{"en":"children of 14 and over","cn":"14 岁及 14 岁以上的儿童"},"pos":"adverb"},{"en":"not used or needed","cn":"剩余；未用；不需要","ex":{"en":"If there's any food left over, put it in the fridge.","cn":"要是有剩下的饭菜，就放到冰箱里。"},"pos":"adverb"},{"en":"ended","cn":"结束","ex":{"en":"By the time we arrived the meeting was over.","cn":"我们到达时，会议已经结束了。"},"pos":"adverb"},{"en":"again","cn":"又；再；重新","lab":"North American English","ex":{"en":"He repeated it several times over until he could remember it.","cn":"他重复了几遍直到能记住为止。"},"pos":"adverb"},{"en":"used to talk about somebody/something changing position","cn":"（表示位置变换）改变，掉换","ex":{"en":"He's gone over to the enemy (= joined them).","cn":"他已变节投敌。"},"pos":"adverb"},{"en":"used when communicating by radio","cn":"（用于无线通话）完毕","ex":{"en":"Message received. Over (= it is your turn to speak).","cn":"消息收到了。完毕。"},"pos":"adverb"},{"en":"a series of six balls bowled by the same person","cn":"一轮投球（同一个投球手连续投出的六个球）","ex":{"en":"Chadwick dismissed two batsmen in the same over.","cn":"查德威克在同一轮中解雇了两名击球手。"},"pos":"noun"},{"en":"more than usual; too much","cn":"太；过于","ex":{"en":"overproduction","cn":"生产过剩"},"pos":"prefix"},{"en":"completely","cn":"完全；全面；整体地","ex":{"en":"overjoyed","cn":"十分高兴"},"pos":"prefix"},{"en":"upper; outer; extra","cn":"上面；外面；额外","ex":{"en":"overcoat","cn":"长大衣"},"pos":"prefix"},{"en":"over; above","cn":"上方；上空","ex":{"en":"overcast","cn":"阴云密布"},"pos":"prefix"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"在…的上方；在…的上面；在…的上空","en":"If one thing is over another thing or is moving over it, the first thing is directly above the second, either resting on it, or with a space between them.","ex":{"en":"He looked at himself in the mirror over the table.","cn":"他对着桌子上方的镜子照了照。"}},{"pos":"PREP 介词","cn":"搭挂在…的上面","en":"If one thing is over another thing, it is supported by it and its ends are hanging down on each side of it.","ex":{"en":"A grey mackintosh was folded over her arm","cn":"她胳膊上搭着一件灰色雨衣。"}},{"pos":"PREP 介词","cn":"（部分或完全地）覆盖在…的上面","en":"If one thing is over another thing, it covers part or all of it.","ex":{"en":"His hair fell over his brow instead of being brushed straight back","cn":"他的头发没有整齐地往后梳，而是搭在前额。"}},{"pos":"PREP 介词","cn":"（身体上部）俯在…的上面","en":"If you lean over an object, you bend your body so that the top part of it is above the object.","ex":{"en":"They stopped to lean over a gate","cn":"他们停下来，身子探过一扇栅栏门。"}},{"pos":"PREP 介词","cn":"从…上面（看过去）；隔着…（交谈）","en":"If you look over or talk over an object, you look or talk across the top of it.","ex":{"en":"I went and stood beside him, looking over his shoulder.","cn":"我走过去站在他身边，从他的肩头望过去。"}},{"pos":"PREP 介词","cn":"(从…)可以看见;俯瞰","en":"If a window has a view over an area of land or water, you can see the land or water through the window.","ex":{"en":"...a light and airy bar with a wonderful view over the River Amstel","cn":"可将阿姆斯特尔河美景尽收眼底的明亮通风的酒吧"}},{"pos":"PREP 介词","cn":"（穿）过，（跨）过，（越）过（障碍、边界等）","en":"If someone or something goes over a barrier, obstacle, or boundary, they get to the other side of it by going across it, or across the top of it.","ex":{"en":"Policemen jumped over the wall of the Spanish Embassy in pursuit","cn":"警察在追捕中跳过西班牙大使馆的围墙。"}},{"pos":"PREP 介词","cn":"从一边至…的另一边","en":"If someone or something moves over an area or surface, they move across it, from one side to the other.","ex":{"en":"She ran swiftly over the lawn to the gate","cn":"她一溜烟穿过草地跑到了大门口。"}},{"pos":"PREP 介词","cn":"在…的另一边；在…的对面","en":"If something is on the opposite side of a road or river, you can say that it is over the road or river.","ex":{"en":"...Richard Garrick, who lived in the house over the road.","cn":"住在马路对面那所房子里的理查德·加里克"}},{"pos":"ADV 副词","cn":"去，到（某处）","en":"If you go over to a place, you go to that place.","ex":{"en":"I got out the car and drove over to Dervaig","cn":"我把车开出来，驶向德韦格。"}},{"pos":"ADV 副词","cn":"在那边；在近旁","en":"You can use over to indicate a particular position or place a short distance away from someone or something.","ex":{"en":"He noticed Rolfe standing silently over by the window","cn":"他注意到罗尔夫一声不吭地站在窗户旁边。"}},{"pos":"ADV 副词","cn":"（突然或猛力地）（倒）下，（掉）下","en":"You use over to say that someone or something falls towards or onto the ground, often suddenly or violently.","ex":{"en":"If he drinks more than two glasses of wine he falls over","cn":"他喝酒超过两杯就会醉倒在地。"}},{"pos":"ADV 副词","cn":"（翻）转过来","en":"If something rolls over or is turned over, its position changes so that the part that was facing upwards is now facing downwards. →see usage note at:","ex":{"en":"His car rolled over after a tyre was punctured","cn":"一只轮胎被扎破后，他的车翻了个底朝天。"}},{"pos":"PREP-PHRASE 短语介词","cn":"到处；遍及","en":"All over a place means in every part of it.","ex":{"en":"...doctors who work all over the country.","cn":"在全国各地工作的医生"}},{"pos":"PHRASE 短语","cn":"在这边；到这边；在身处国","en":"Over here means near you, or in the country you are in.","ex":{"en":"Why don't you come over here tomorrow evening","cn":"你明天晚上过来吧。"}},{"pos":"PHRASE 短语","cn":"在那边；到那边；在另一国","en":"Over there means in a place a short distance away from you, or in another country.","ex":{"en":"The cafe is just across the road over there","cn":"咖啡馆就在那边马路对面。"}},{"pos":"","cn":"","en":"the world over→see: ;"},{"pos":"PREP 介词","cn":"超过；在…以上","en":"If something is over a particular amount, measurement, or age, it is more than that amount, measurement, or age.","ex":{"en":"Cigarettes kill over a hundred thousand Britons every year","cn":"每年香烟夺去10万多英国人的生命。"}},{"pos":"PREP-PHRASE 短语介词","cn":"多于（正常数量）；除了…之外（还）","en":"Over and above an amount, especially a normal amount, means more than that amount or in addition to it.","ex":{"en":"Expenditure on education has gone up by seven point eight per cent over and above inflation","cn":"扣除通货膨胀因素，教育支出实际增长了7.8%。"}},{"pos":"ADV 副词","cn":"剩余；剩下","en":"If you say that you have some food or money over, you mean that it remains after you have used all that you need.","ex":{"en":"Larsons pay me well enough, but there's not much over for luxuries when there's two of you to live on it","cn":"拉森公司给我的薪水算是不错，但是两个人靠这份工资生活便没有多少闲钱买奢侈品了。"}},{"pos":"ADV 副词","cn":"再一次;又一次；重复地","en":"If you do something over, you do it again or start doing it again from the beginning.","ex":{"en":"She said if she had the chance to do it over, she would have hired a press secretary","cn":"她说如果有机会从头来过，她会雇一位新闻秘书。"}},{"pos":"PHRASE 短语","cn":"（强调发生不止一次）两次/三次","en":"If you say that something happened twice over ,three times over and so on, you are stating the number of times that it happened and emphasizing that it happened more than once.","ex":{"en":"He had to have everything spelled out twice over for him.","cn":"他不得不把所有事项都对他详细说明了两次。"}},{"pos":"PHRASE 短语","cn":"再一次；重新","en":"If you do something over again, you do it again or start doing it again from the beginning.","ex":{"en":"When you realise they are singing the same songs over again, the novelty wears off","cn":"当你意识到他们开始从头演唱同样的歌曲时，新鲜感也就没有了。"}},{"pos":"PHRASE 短语","cn":"（指令人疲倦、厌烦、不快地）再一次，又一次，重新","en":"If you say that something is happening all over again, you are emphasizing that it is happening again, and you are suggesting that it is tiring, boring, or unpleasant.","ex":{"en":"He doesn't want the hassle all over again","cn":"他不想再惹这种麻烦了。"}},{"pos":"PHRASE 短语","cn":"一再；再三；反复","en":"If you say that something happened over and over or over and over again, you are emphasizing that it happened many times.","ex":{"en":"He plays the same songs over and over","cn":"他一遍又一遍地放着同样的歌曲。"}},{"pos":"ADJ 形容词","cn":"结束的；完了的","en":"If an activity is over or all over, it is completely finished.","ex":{"en":"Warplanes that have landed there will be kept until the war is over","cn":"降落在那里的战斗机将一直扣留到战争结束。"}},{"pos":"PREP 介词","cn":"从（某一疾病或经历）中恢复过来","en":"If you are over an illness or an experience, it has finished and you have recovered from its effects.","ex":{"en":"I'm glad that you're over the flu","cn":"你的流感好了，我真高兴。"}},{"pos":"PREP 介词","cn":"（控制或影响）对…起作用","en":"If you have control or influence over someone or something, you are able to control them or influence them.","ex":{"en":"He's never had any influence over her","cn":"他从未对她有过任何影响力。"}},{"pos":"PREP 介词","cn":"关于；由于","en":"You use over to indicate what a disagreement or feeling relates to or is caused by.","ex":{"en":"The women were making a fuss over nothing.","cn":"这些女人是在无谓地小题大做。"}},{"pos":"PREP 介词","cn":"在…期间","en":"If something happens over a particular period of time or over something such as a meal, it happens during that time or during the meal.","ex":{"en":"The number of attacks on the capital had gone down over the past week","cn":"上一周对首都的袭击次数已经减少了。"}},{"pos":"PREP 介词","cn":"通过（电话、广播等）","en":"You use over to indicate that you give or receive information using a telephone, radio, or other piece of electrical equipment.","ex":{"en":"I'm not prepared to discuss this over the telephone","cn":"我不想在电话里讨论这件事。"}},{"pos":"PREP-PHRASE 短语介词","cn":"（广播或电视节目中的主持人用语）下面交给…","en":"The presenter of a radio or television programme says 'over to someone' to indicate the person who will speak next.","ex":{"en":"With the rest of the sports news, over to Colin Maitland.","cn":"下面由科林·梅特兰接着为大家播报其他体育新闻。"}},{"pos":"CONVENTION 惯用语","cn":"（无线电通讯用语）完毕，请回答","en":"When people such as the police or the army are using a radio to communicate, they say 'Over' to indicate that they have finished speaking and are waiting for a reply."},{"pos":"N-COUNT 可数名词","cn":"（板球运动中）一轮6个（未让对方得分的）有效投球","en":"In cricket, an over consists of six correctly bowled balls.","ex":{"en":"At the start of the last over, bowled by Chris Lewis, the Welsh county were favourites.","cn":"在最后一轮由克里斯·刘易斯连续投出6个有效球之前，威尔士郡队本来胜券在握。"}}]},"examples":[{"en":"He did the work so badly that I had to do it all over again myself.","cn":"他活做得太糟糕了，我只好亲自从头再做一次。"},{"en":"They had a wonderful view over the park.","cn":"他们放眼望去，把公园美丽的景色尽收眼底。"}]},"overwhelming":{"media":{"uk":"media/uk/overwhelming__gb_1.mp3","us":"media/us/overwhelming__us_1.mp3"},"oxford":{"phon":"ˌəʊvəˈwelmɪŋ","pos":"adjective","senses":[{"en":"very great or very strong; so powerful that you cannot resist it or decide how to react","cn":"巨大的；压倒性的；无法抗拒的","ex":{"en":"The evidence against him was overwhelming.","cn":"对他不利的证据确凿，无法抵赖。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极强烈的；势不可挡的；令人不知所措的","en":"If something is overwhelming, it affects you very strongly, and you do not know how to deal with it.","ex":{"en":"The task won't feel so overwhelming if you break it down into small, easy-to-accomplish steps","cn":"如果将这个任务细分为简单易行的若干步骤来做，便不会感到如此无所适从。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（数量）巨大的，压倒性的","en":"You can use overwhelming to emphasize that an amount or quantity is much greater than other amounts or quantities.","ex":{"en":"The overwhelming majority of small businesses go broke within the first twenty-four months","cn":"绝大多数小企业在头两年内就破产了。"}}]},"examples":[{"en":"The evidence against him was overwhelming.","cn":"对他不利的证据确凿，无法抵赖。"},{"en":"The overwhelming majority of those present were in favour of the plan.","cn":"绝大多数与会者都赞同这个计划。"}]},"over-":{"oxford":{"phon":"ˈəʊvə(r)","pos":"prefix","senses":[{"en":"more than usual; too much","cn":"太；过于"},{"en":"completely","cn":"完全地"}]},"collins":{"senses":[{"pos":"PREFIX 前缀","cn":"（用于形容词或动词后）表示“过分”，“过度”","en":"You can add over- to an adjective or verb to indicate that a quality exists or an action is done to too great an extent. For example, if you say that someone is being over-cautious, you mean that they are being too cautious.","ex":{"en":"Tony looked tired and over-anxious","cn":"托尼看起来很疲惫而且过分焦虑。"}}]},"media":{"uk":"media/uk/over__1_gb_1.mp3","us":"media/us/over__1_us_1.mp3"},"examples":[{"en":"over-optimistic","cn":"过分乐观的"},{"en":"overconfident","cn":"过分自信的"}]},"overcrowded":{"media":{"uk":"media/uk/overcrowded__gb_1.mp3","us":"media/us/overcrowded__us_1.mp3"},"oxford":{"phon":"ˌəʊvəˈkraʊdɪd","pos":"adjective","senses":[{"en":"with too many people or things in it","cn":"过于拥挤的","ex":{"en":"overcrowded cities/prisons","cn":"拥挤不堪的城市／监狱"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（地方）过度拥挤的","en":"An overcrowded place has too many things or people in it.","ex":{"en":"...one of the most overcrowded prisons in the country.","cn":"该国最拥挤的监狱之一"}}]},"examples":[{"en":"Too many poor people are living in overcrowded conditions.","cn":"有太多贫民的居住环境十分拥挤。"},{"en":"overcrowded cities/prisons","cn":"拥挤不堪的城市/监狱"}]},"overland":{"oxford":{"phon":"ˈəʊvəlænd","pos":"adverb","senses":[{"en":"across the land; by land, not by sea or by air","cn":"横跨陆地的；通过陆路的","ex":{"en":"to travel overland","cn":"经陆路前往"}},{"en":"across the land; by land, not by sea or by air","cn":"横跨陆地的；通过陆路的","ex":{"en":"an overland route","cn":"陆上路线"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"经由陆路的；横跨陆地的","en":"An overland journey is made across land rather than by ship or aeroplane.","ex":{"en":"...an overland journey through Iraq, Turkey, Iran and Pakistan","cn":"途径伊拉克、土耳其、伊朗和巴基斯坦的陆路旅程"}}]},"media":{"uk":"media/uk/overland__gb_1.mp3","us":"media/us/overland__us_1.mp3"},"examples":[{"en":"to travel overland","cn":"作陆上旅行"},{"en":"an overland route","cn":"陆上路线"}]},"oven":{"oxford":{"phon":"ˈʌvn","pos":"noun","senses":[{"en":"the part of a cooker that is like a box with a door on the front, in which food is cooked or heated","cn":"烤箱；烤炉","ex":{"en":"Take the cake out of the oven.","cn":"把蛋糕从烤箱中取出来。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"烤箱；烤炉","en":"An oven is a device for cooking that is like a box with a door. You heat it and cook food inside it.","ex":{"en":"Put the onions and ginger in the oven and let them roast for thirty minutes.","cn":"将洋葱和姜放进烤箱烘烤30分钟。"}}]},"media":{"uk":"media/uk/oven__gb_1.mp3","us":"media/us/oven__us_1.mp3"},"examples":[{"en":"Open a window, it's like an oven in here!","cn":"打开窗户。这儿热得像火炉！"},{"en":"Take the cake out of the oven.","cn":"把蛋糕从烤箱中取出来。"}]},"overlap":{"media":{"uk":"media/uk/overlap__gb_1.mp3","us":"media/us/overlap__us_1.mp3"},"oxford":{"phon":"ˌəʊvəˈlæp","pos":"verb","senses":[{"en":"if one thing overlaps another, or the two things overlap, part of one thing covers part of the other","cn":"（物体）部分重叠，交叠","g":"[transitive, intransitive]","ex":{"en":"A fish’s scales overlap each other.","cn":"鱼鳞一片片上下交叠。"}},{"en":"to make two or more things overlap","cn":"使部分重叠","g":"[transitive]","ex":{"en":"You will need to overlap the pieces of wood slightly.","cn":"你得使这些木片像鱼鳞片似的搭叠起来。"}},{"en":"if two events overlap or overlap each other, the second one starts before the first one has finished","cn":"（时间上）部分重叠","g":"[intransitive, transitive]"},{"en":"to cover part of the same area of interest, knowledge, responsibility, etc.","cn":"（范围方面）部分重叠","g":"[intransitive, transitive]","ex":{"en":"Our jobs overlap slightly, which sometimes causes difficulties.","cn":"我们的工作略有重叠，所以有时引起一些困难。"}},{"en":"a shared area of interest, knowledge, responsibility, etc.","cn":"（范围方面的）重叠部分","g":"[countable, uncountable]","ex":{"en":"There is (a) considerable overlap between the two subjects.","cn":"两门科目之间有相当多的共通之处。"},"pos":"noun"},{"en":"the amount by which one thing covers another thing","cn":"（物体的）重叠部分，重叠量","g":"[countable, uncountable]","ex":{"en":"an overlap of 5 cm on each roof tile","cn":"每片房瓦上 5 厘米的重叠度"},"pos":"noun"},{"en":"a period of time in which two events or activities happen together","cn":"（两事发生的）重叠时间，交接时期","g":"[uncountable, singular]","ex":{"en":"There will be an overlap of a week while John teaches Ann the job.","cn":"将有一周的交接期可以让约翰教导安如何接手工作。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-RECIP-ERG","cn":"与…互搭；与…复叠；（使）相叠","en":"If one thing overlaps another, or if you overlap them, a part of the first thing occupies the same area as a part of the other thing. You can also say that two things overlap .","ex":{"en":"When the bag is folded flat, the bag bottom overlaps one side of the bag","cn":"袋子平整折起后，底面与一侧交叠。"}},{"pos":"V-RECIP 相互动词","cn":"（在主题、人物、时间等上）（与…）部分相同，（与…）部分交叉","en":"If one idea or activity overlaps another, or overlaps with another, they involve some of the same subjects, people, or periods of time.","ex":{"en":"Elizabeth met other Oxford intellectuals some of whom overlapped Naomi's world","cn":"伊丽莎白结识了其他一些牛津大学的学者，其中有几位娜奥米也认识。"}}]},"examples":[{"en":"There will be an overlap of a week while John teaches Ann the job.","cn":"将有一周的交接期可以让约翰教导安如何接手工作。"},{"en":"Our jobs overlap slightly, which sometimes causes difficulties.","cn":"我们的工作略有重叠，所以有时引起一些困难。"}]},"overview":{"oxford":{"phon":"ˈəʊvəvjuː","pos":"noun","senses":[{"en":"a general description or an outline of something","cn":"概述；纵览；概论；概况","ex":{"en":"The second chapter will provide an overview of the issues involved.","cn":"第二章将对相关议题作出概述。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"概观；概览；概述","en":"An overview of a situation is a general understanding or description of it as a whole.","ex":{"en":"The central section of the book is a historical overview of drug use.","cn":"该书的核心部分对毒品的使用作了历史概述。"}}]},"media":{"uk":"media/uk/overview__gb_1.mp3","us":"media/us/overview__us_1.mp3"}},"overhead":{"media":{"uk":"media/uk/overhead__gb_1.mp3","us":"media/us/overhead__us_1.mp3"},"oxford":{"phon":"ˌəʊvəˈhed","pos":"adverb","senses":[{"en":"above your head; in the sky","cn":"在头上方；在空中","ex":{"en":"Planes flew overhead constantly.","cn":"飞机不断从头顶上飞过。"}},{"en":"above your head; raised above the ground","cn":"头上方的；地面以上的；高架的","ex":{"en":"overhead power lines","cn":"架空电力线"},"pos":"adjective"},{"en":"connected with the general costs of running a business or an organization, for example paying for rent or electricity","cn":"经费的；管理费用的","g":"[only before noun]","ex":{"en":"overhead costs","cn":"营运开支"},"pos":"adjective"},{"en":"regular costs that you have when you are running a business or an organization, such as rent, electricity, wages, etc.","cn":"经费；营运费用；经常性开支","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"在头顶上的；在上面的；高架的","en":"You use overhead to indicate that something is above you or above the place that you are talking about.","ex":{"en":"She turned on the overhead light and looked around the little room.","cn":"她打开头顶上方的灯，环视了一圈这个小房间。"}}]},"examples":[{"en":"Planes flew overhead constantly.","cn":"飞机不断从头顶上飞过。"},{"en":"Thunder boomed in the sky overhead.","cn":"雷声在天空中隆隆作响。"}]},"oversight":{"media":{"uk":"media/uk/oversight__gb_1.mp3","us":"media/us/oversight__us_1.mp3"},"oxford":{"phon":"ˈəʊvəsaɪt","pos":"noun","senses":[{"en":"the fact of making a mistake because you forget to do something or you do not notice something","cn":"疏忽；忽略；失察","g":"[countable, uncountable]","ex":{"en":"I didn't mean to leave her name off the list; it was an oversight.","cn":"我不是有意在名单上漏掉她的名字的，这是个疏忽。"}},{"en":"the state of being in charge of somebody/something","cn":"负责；照管","g":"[uncountable]","lab":"formal","ex":{"en":"The committee has oversight of finance and general policy.","cn":"该委员会负责处理财政和一般性政策。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"疏忽；忽略；失察","en":"If there has been an oversight, someone has forgotten to do something which they should have done.","ex":{"en":"William was angered and embarrassed by his oversight","cn":"威廉因为自己的疏忽而羞愤交加。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"照管；监督；负责","en":"If someone has oversight of a process or system, they are responsible for making sure that it works efficiently and correctly.","ex":{"en":"...a new system, where there'll be greater oversight of doctors","cn":"加强医生监管的新体制"}}]},"examples":[{"en":"I didn't mean to leave her name off the list; it was an oversight.","cn":"我不是有意在名单上漏掉她的名字的，这是个疏忽。"},{"en":"The committee has oversight of finance and general policy.","cn":"委员会负责处理财政和综合政策。"}]},"over-the-counter":{"oxford":{"phon":"ˌəʊvə ðə ˈkaʊntə(r)","pos":"adjective","senses":[{"en":"that can be obtained without a prescription (= a written order from a doctor)","cn":"无需处方可买到的；非处方的"},{"en":"not appearing in an official stock exchange list","cn":"场外交易的","lab":"business, North American English，，"}]},"media":{"uk":"media/uk/over_the_counter_1_gb_1.mp3","us":"media/us/over_the_counter_1_us_1.mp3"},"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]}},"overseen":{"oxford":{"phon":"ˌəʊvəˈsiː","pos":"verb","senses":[{"en":"to watch sb/sth and make sure that a job or an activity is done correctly","cn":"监督；监视"}]}},"overalls":{"oxford":{"phon":"ˌəʊvərˈɔːl","pos":"adjective","senses":[{"en":"including all the things or people that are involved in a particular situation; general","cn":"全面的；综合的；总体的"},{"en":"including everything or everyone; in total","cn":"全部；总计"}]},"media":{"img":["media/thumb/overalls.jpg"]}},"overlapping":{"oxford":{"phon":"ˌəʊvəˈlæp","pos":"verb","senses":[{"en":"if one thing overlaps another, or the two things overlap , part of one thing covers part of the other （","cn":"物体）部分重叠，交叠"},{"en":"to make two or more things overlap","cn":"使部分重叠"}]}},"overvalues":{"oxford":{"phon":"ˌəʊvəˈvæljuː","pos":"verb","senses":[{"en":"to put too high a value on sth","cn":"估计过高；过于重视"}]}},"overlooking":{"oxford":{"phon":"ˌəʊvəˈlʊk","pos":"verb","senses":[{"en":"to fail to see or notice sth","cn":"忽略；未注意到"},{"en":"to see sth wrong or bad but decide to ignore it （","cn":"对不良现象等）不予理会，视而不见"}]}},"overweight":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"太胖的；超重的","en":"Someone who is overweight weighs more than is considered healthy or attractive. →see usage note at:","ex":{"en":"Being even moderately overweight increases your risk of developing high blood pressure.","cn":"即使是轻度超重也会增加患高血压的风险。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having too much flesh on your body. It is rude to tell someone that they are fat. It is also better not to use any of these words when talking directly to someone about their body","cn":""},{"en":"weighing more than you should","cn":""},{"en":"used when saying that someone has a big body. Large is more common than big in written English","cn":""}]},"collocations":{"phrases":["VERBS be, look You don't look overweight. | become, get Don't let yourself get overweight.","ADV. extremely, grossly, heavily, seriously, very | a bit, a little, rather, slightly","PHRASES a few pounds, two stone, etc. overweight"]},"media":{"uk":"media/ldoce/hwd/bre/8/overweight0205.mp3","us":"media/ldoce/hwd/ame/5/overweight.mp3"},"examples":[{"en":"She was only a few pounds overweight.","cn":"她只是超重几磅而已。"},{"en":"overweight baggage","cn":"超重的行李"}],"oxford":{"phon":"ˌəʊvəˈweɪt","pos":"adjective","senses":[{"en":"too heavy, in a way that may be unhealthy","cn":"超重的；过重的","lab":"British English","ex":{"en":"She was only a few pounds overweight.","cn":"她只是超重几磅而已。"}},{"en":"above an allowed weight","cn":"超过限制重量的；过重的","ex":{"en":"overweight baggage","cn":"超重的行李"}}]}},"overturn":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）翻转；（使）倾覆；（使）倒下","en":"If something overturns or if you overturn it, it turns upside down or on its side.","ex":{"en":"The lorry veered out of control, overturned and smashed into a wall","cn":"卡车突然失控，翻倒撞上了一堵墙。"}},{"pos":"VERB 动词","cn":"推翻，撤销（判决）","en":"If someone in authority overturns a legal decision, they officially decide that that decision is incorrect or not valid.","ex":{"en":"When the Russian parliament overturned his decision, he backed down","cn":"俄罗斯议会推翻了他的决定，他只好作罢。"}},{"pos":"VERB 动词","cn":"颠覆，破坏（政府或体系）","en":"To overturn a government or system means to remove it or destroy it.","ex":{"en":"He accused his opponents of wanting to overturn the government.","cn":"他指责反对派企图颠覆政府。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to completely change something, especially so that it is much better","cn":""},{"en":"to make something become a completely different thing or make someone become a completely different kind of person","cn":""},{"en":"to completely and permanently change the way people do something or think about something, especially because of a new idea or invention","cn":""}]},"collocations":{"phrases":["ADV. completely She completely overturned my preconceptions about film stars.","VERB + OVERTURN seek to, try to seeking to overturn his conviction for armed robbery | fail to","PHRASES be easily overturned This argument seems convincing, but is easily overturned."]},"media":{"uk":"media/ldoce/hwd/bre/d/overturn0205.mp3","us":"media/ldoce/hwd/ame/8/overturn.mp3"},"examples":[{"en":"He stood up quickly, overturning his chair.","cn":"他猛然站起来，弄翻了椅子。"},{"en":"His sentence was overturned by the appeal court.","cn":"上诉法庭撤销了对他的判决。"}],"oxford":{"phon":"ˌəʊvəˈtɜːn","pos":"verb","senses":[{"en":"if something overturns, or if somebody overturns it, it turns into a position in which the top of it is where the bottom of it normally is or on its side","cn":"倾倒；倾覆；翻掉","g":"[intransitive, transitive]","ex":{"en":"The car skidded and overturned.","cn":"汽车打滑翻倒了。"}},{"en":"to officially decide that a legal decision, etc. is not correct, and to make it no longer legally recognized","cn":"推翻，撤销（判决等）","g":"[transitive]","ex":{"en":"to overturn a decision/conviction/verdict","cn":"撤销决定／定罪／裁决"}},{"en":"to show that a belief or an idea is not correct","cn":"（思想上）颠覆，彻底改变","ex":{"en":"She completely overturned my preconceptions about film stars.","cn":"她彻底打破了我对电影明星的成见。"}}]}},"overgrown":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"杂草丛生的；植被蔓生的","en":"If a garden or other place is overgrown, it is covered with a lot of untidy plants because it has not been looked after.","ex":{"en":"We hurried on until we reached a courtyard overgrown with weeds","cn":"我们匆匆往前走，来到一个野草丛生的院子。"}},{"pos":"ADJ 形容词","cn":"（成年人）不成熟的，孩子气的","en":"If you describe an adult as an overgrown child, you mean that their behaviour and attitudes are like those of a child, and that you dislike this.","ex":{"en":"...a bunch of overgrown kids","cn":"一帮大孩子"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"covered with plants that have grown in an uncontrolled way","cn":"植物蔓生的﹐杂草丛生的"},{"en":"when grass or plants are overgrown, they have grown in an uncontrolled way 〔","cn":"杂草或植物〕乱长的﹐丛生的"},{"en":"an adult who behaves like a child – used to show disapproval","cn":"大男生/大孩子〔用于形容孩子气的成人﹐含贬义〕"}]},"collocations":{"phrases":["VERBS be, look | become, get","ADV. extremely, thickly, very | completely The path was completely overgrown.","PREP. with The canal bank was thickly overgrown with last year's brambles."]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdeovergrown.mp3","us":"media/ldoce/hwd/ame/f/overgrown.mp3"},"examples":[{"en":"They act like a pair of overgrown children (= they are adults but they behave like children).","cn":"他俩的举动就像一对大孩子。"},{"en":"The garden's completely overgrown with weeds.","cn":"花园里长满了杂草。"}],"oxford":{"phon":"ˌəʊvəˈɡrəʊn","pos":"adjective","senses":[{"en":"covered with plants that have been allowed to grow wild and have not been controlled","cn":"植物蔓生的；杂草丛生的","ex":{"en":"an overgrown path","cn":"长满野草的小径"}},{"en":"that has grown too large","cn":"过度发展的；长得过大的","lab":"often disapproving","ex":{"en":"an overgrown village","cn":"膨胀过大的村庄"}}]}},"overdue":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（变化或事件）早该发生的","en":"If you say that a change or an event is overdue, you mean that you think it should have happened before now.","ex":{"en":"This debate is long overdue","cn":"这场辩论早该进行了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（钱款）到期未付的，拖欠的","en":"Overdue sums of money have not been paid, even though it is later than the date on which they should have been paid.","ex":{"en":"Teachers have joined a strike aimed at forcing the government to pay overdue salaries and allowances.","cn":"教师加入了旨在迫使政府支付拖欠薪水和津贴的罢工。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（图书馆的书）逾期未还的","en":"An overdue library book has not been returned to the library, even though the date on which it should have been returned has passed."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"arriving or happening after the time that was expected or arranged","cn":""},{"en":"not arriving or doing something at the time that was expected or arranged","cn":""},{"en":"not done or happening by the expected time – used especially about payments that are late or library books that should have been returned","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that's overdue should have happened or been dealt with a long time ago, like the long overdue recognition for the people who rescued motorists in last winter's big snowstorm."}]},"collocations":{"phrases":["VERBS be | become","ADV. long These reforms are long overdue.","PREP. for This system is overdue for reform.","PHRASES months/weeks/years overdue These changes are years overdue."]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdeoverdue.mp3","us":"media/ldoce/hwd/ame/8/overdue.mp3"},"examples":[{"en":"Her baby is two weeks overdue.","cn":"她的胎儿已超过预产期两周了。"},{"en":"A book like this is long overdue.","cn":"像这样的书早就该有人出版了。"}],"oxford":{"phon":"ˌəʊvəˈdjuː","pos":"adjective","senses":[{"en":"not paid, done, returned, etc. by the required or expected time","cn":"（到期）未付的，未做的，未还的；过期的","ex":{"en":"an overdue payment/library book","cn":"逾期的欠款；逾期未还图书馆的书"}},{"en":"that should have happened or been done before now","cn":"早该发生的；早应完成的","ex":{"en":"overdue reforms","cn":"迟来的改革"}}]}},"overhaul":{"collins":{"senses":[{"pos":"VERB 动词","cn":"大修；彻底检修；全面检查","en":"If a piece of equipment is overhauled, it is cleaned, checked thoroughly, and repaired if necessary.","ex":{"en":"They had ensured the plumbing was overhauled a year ago","cn":"他们曾保证水管一年前彻底检修过。"}},{"pos":"VERB 动词","cn":"对…进行彻底革新；全面修订","en":"If you overhaul a system or method, you examine it carefully and make many changes in it in order to improve it.","ex":{"en":"The government said it wanted to overhaul the employment training scheme to make it cost effective","cn":"政府表示希望彻底改革就业培训计划以实现低成本高效益。"}},{"pos":"VERB 动词","cn":"（尤指在体育比赛中）赶上，超过，超越","en":"If someone overhauls a person who is ahead of them, especially in a sports competition, they pass them or become more successful than them.","ex":{"en":"Argentina need to beat Peru by at least four goals to overhaul Brazil and reach the final itself","cn":"阿根廷队至少要赢秘鲁队4球才能超越巴西队进入决赛。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if you repair something that is broken or not working properly, you work on it so that it is in good condition again","cn":""},{"en":"to repair a machine or piece of equipment that is broken or not working properly","cn":""},{"en":"to repair something that is broken or not working, or something that has a hole in it. In American English mend is usually used about clothing","cn":""}]},"vocab":{"pos":"1 v n 2 v","senses":[{"en":"To overhaul is to completely renovate, making major changes in order to repair. A few shutters and a new coat of paint won't come close to fixing that old, boarded-up house — it needs a complete overhaul ."}]},"collocations":{"phrases":["ADV. drastically, radically Within a year the party had drastically overhauled its structure. | completely, thoroughly The plan was complete"]},"media":{"uk":"media/ldoce/hwd/bre/f/overhaul_v0205.mp3","us":"media/ldoce/hwd/ame/1/l3overhaul.mp3"},"examples":[{"en":"He managed to overhaul the leader on the final lap.","cn":"他在最后一圈发力超过了领先的选手。"},{"en":"The engine has been completely overhauled.","cn":"发动机已彻底检修过了。"}],"oxford":{"phon":"ˈəʊvəhɔːl","pos":"noun","senses":[{"en":"an examination of a machine or system, including doing repairs on it or making changes to it","cn":"检修；大修；改造","ex":{"en":"a complete/major overhaul","cn":"彻底检修；大修"}},{"en":"to examine every part of a machine, system, etc. and make any necessary changes or repairs","cn":"彻底检修","ex":{"en":"The engine has been completely overhauled.","cn":"发动机已彻底检修过了。"},"pos":"verb"},{"en":"to come from behind a person you are competing against in a race and go past them","cn":"赶上，超过（赛跑对手）","ex":{"en":"He managed to overhaul the leader on the final lap.","cn":"他在最后一圈发力超过了领先的选手。"},"pos":"verb"}]}},"ovation":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"热烈欢迎；热烈鼓掌","en":"An ovation is a large amount of applause from an audience for a particular performer or speaker.","ex":{"en":"They had lost by a wide margin, but their supporters gave them a defiant, loyal ovation.","cn":"他们以较大的差距败北，但支持者们还是给予了热烈的掌声，以示对对手的不服和对他们的忠诚。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to hit your hands together loudly and quickly to show that you approve of and are pleased with a play, someone's performance, someone's actions etc","cn":""},{"en":"if people applaud , they clap excitedly, and often for a long time, in order to show how much they liked something or to show their support for someone","cn":""},{"en":"to give a loud, happy shout expressing admiration, approval, and often excitement, for example at a sports event or after a speech","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Hear that applause and cries of \"Bravo\"? Your audience is giving you an ovation , or praise for a great performance."}]},"collocations":{"phrases":["ADJ. enthusiastic, huge, long, loud, rapturous, thunderous | standing The audience gave her a standing ovation for her performance.","VERB + OVATION give sb | get, receive He received the longest ovation of the evening. | bring, earn, win","PREP. to an ~ He came off the field to a huge ovation. | ~ from The final piece won her a rapturous ovation from the audience."]},"media":{"uk":"media/ldoce/hwd/bre/b/ovation0205.mp3","us":"media/ldoce/hwd/ame/7/ovation.mp3"},"examples":[{"en":"The soloist got a ten-minute standing ovation (= in which people stand up from their seats).","cn":"独奏演员受到了长达十分钟的起立鼓掌欢呼。"},{"en":"to give sb a huge/rapturous/rousing ovation","cn":"对某人万分的/狂热的/热烈的欢迎"}],"oxford":{"phon":"əʊˈveɪʃn","pos":"noun","senses":[{"en":"enthusiastic clapping by an audience as a sign of their approval","cn":"热烈鼓掌；热烈欢迎","ex":{"en":"to give somebody a huge/rapturous/rousing ovation","cn":"对某人表示万分的／狂热的／热烈的欢迎"}}]}},"overture":{"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"（歌剧、戏剧等的）序曲，前奏曲","en":"An overture is a piece of music, often one that is the introduction to an opera or play.","ex":{"en":"The programme opened with the overture to Wagner's Flying Dutchman.","cn":"节目以瓦格纳的歌剧《漂泊的荷兰人》的序曲开场。"}},{"pos":"N-COUNT 可数名词","cn":"（友好或求爱的）主动表示，姿态，提议","en":"If you make overtures to someone, you behave in a friendly or romantic way towards them.","ex":{"en":"He had lately begun to make clumsy yet endearing overtures of friendship","cn":"最近他开始主动表示友好，样子笨拙却又招人喜爱。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short piece of music written as an introduction to a long piece of music, especially an opera 〔","cn":"尤指歌剧的〕序曲﹐前奏曲"},{"en":"an attempt to begin a friendly relationship with a person, country etc 〔","cn":"试图与某人﹑某国等建立友好关系的〕主动表示﹐姿态"},{"en":"if an event is an overture to a more important event, it happens just before it and makes you expect it","cn":"是一个序幕〔表示某事是另一更为重要之事的开端〕"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"An overture is a piece of music played by an orchestra at the beginning of an opera or play. When an overture begins, the actors take their places and wait for the curtain to rise."}]},"collocations":{"phrases":["ADJ. friendly | diplomatic, peace, sexual","VERB + OVERTURE make | receive | respond to | reject, spurn She spurned his overtures of love.","PREP. ~s of overtures of friendship | ~s to He made friendly overtures to his new neighbours. 2 piece of music","ADJ. operatic, symphonic","PREP. ~ to the overture to Mozart's &lsquo;Don Giovanni&rsquo;"]},"media":{"uk":"media/ldoce/hwd/bre/a/overture0205.mp3","us":"media/ldoce/hwd/ame/8/overture.mp3"},"examples":[{"en":"Prokofiev's overture to ‘Romeo and Juliet’","cn":"普罗科菲耶夫的《罗密欧与朱丽叶》的序曲"},{"en":"He began making overtures to a number of merchant banks.","cn":"他开始主动同一些投资银行接触。"}],"oxford":{"phon":"ˈəʊvətʃʊə(r)","pos":"noun","senses":[{"en":"a piece of music written as an introduction to an opera or a ballet","cn":"（歌剧或芭蕾舞的）序曲，前奏曲","ex":{"en":"Prokofiev’s overture to ‘Romeo and Juliet’","cn":"普罗科菲耶夫《罗密欧与朱丽叶》序曲"}},{"en":"a suggestion or an action by which somebody tries to make friends, start a business relationship, have discussions, etc. with somebody else","cn":"友好姿态；建议","g":"[usually plural]","ex":{"en":"He began making overtures to a number of merchant banks.","cn":"他开始主动同一些投资银行接触。"}}]}},"overtone":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"弦外之音；言外之意；暗示","en":"If something has overtones of a particular thing or quality, it suggests that thing or quality but does not openly express it.","ex":{"en":"The strike has taken on overtones of a civil rights campaign","cn":"罢工带上了民权运动的意味。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"signs of an emotion or attitude that is not expressed directly 〔","cn":"情感或态度〕含蓄的表示﹐暗示﹐弦外之音"},{"en":"a higher musical note that sounds together with the main note","cn":"泛音"}]},"collocations":{"phrases":["ADJ. strong a play with strong religious overtones | serious | negative The word &lsquo;cheap&rsquo; has negative overtones. | emotional, mo","VERB + OVERTONE carry, have | take on The organization's cultural activities took on political overtones."]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41overtone.mp3","us":"media/ldoce/hwd/ame/8/overtone.mp3"},"examples":[{"en":"There were political overtones to the point he was making.","cn":"他的论点有政治寓意。"},{"en":"There were overtones of anger in his voice.","cn":"他的语气里含着怒意。"}],"oxford":{"phon":"ˈəʊvətəʊn","pos":"noun","senses":[{"en":"an attitude or an emotion that is suggested and is not expressed in a direct way","cn":"弦外之音；言外之意；暗示","ex":{"en":"There were political overtones to the point he was making.","cn":"他的论点有政治寓意。"}}]}},"overthrow":{"collins":{"senses":[{"pos":"VERB 动词","cn":"推翻；打倒；将…赶下台","en":"When a government or leader is overthrown, they are removed from power by force.","ex":{"en":"That government was overthrown in a military coup three years ago.","cn":"那个政府在3年前的军事政变中被推翻。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to get rid of a leader, someone in authority etc","cn":""},{"en":"to take power away from a leader or government, especially by force","cn":""},{"en":"force a leader out of his or her position of power","cn":""}]},"vocab":{"pos":"1 v n 2 n","senses":[{"en":"When you overthrow a ruler or a regime, you throw them out, usually by force. If you're a rebel you may plan to overthrow the current government and install a new regime."}]},"collocations":{"phrases":["ADJ. attempted | violent","VERB + OVERTHROW bring about, lead to | plot","PREP. ~ of to bring about the overthrow of the military dictatorship"]},"media":{"uk":"media/ldoce/hwd/bre/d/overthrow_v0205.mp3","us":"media/ldoce/hwd/ame/c/l3overthrow.mp3"},"examples":[{"en":"The president was overthrown in a military coup.","cn":"总统在军事政变中被赶下台。"},{"en":"Rebels were already making plans to overthrow the government.","cn":"反叛者已在密谋颠覆政府。"}],"oxford":{"phon":"ˌəʊvəˈθrəʊ","pos":"verb","senses":[{"en":"to remove a leader or a government from a position of power by force","cn":"推翻；打倒；赶下台","ex":{"en":"The president was overthrown in a military coup.","cn":"总统在军事政变中被赶下台。"}},{"en":"the act of taking power by force from a leader or government","cn":"推翻；打倒","ex":{"en":"He was president until his overthrow in 1995.","cn":"他一直担任总统，直到 1995 年被推翻。"},"pos":"noun"}]}},"overjoyed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"欣喜若狂的；万分高兴的","en":"If you are overjoyed, you are extremely pleased about something.","ex":{"en":"Shelley was overjoyed to see me","cn":"谢利见到我万分高兴。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very happy because something good has happened","cn":""},{"en":"very happy and excited about something","cn":""},{"en":"very happy because you have heard some good news","cn":""}]},"collocations":{"phrases":["VERBS be, look, seem, sound","ADV. less than, not exactly She was not exactly overjoyed to see us again.","PREP. about They're all overjoyed about it. | at overjoyed at the thought of having a son | by We are overjoyed by this decision. | with Mr "]},"media":{"uk":"media/ldoce/hwd/bre/9/overjoyed0205.mp3","us":"media/ldoce/hwd/ame/6/overjoyed.mp3"},"examples":[{"en":"We were overjoyed to hear their good news.","cn":"听到他们的好消息，我们都大喜过望。"},{"en":"She was overjoyed that her article had been published.","cn":"她的文章发表了，这使她高兴极了。"}],"oxford":{"phon":"ˌəʊvəˈdʒɔɪd","pos":"adjective","senses":[{"en":"extremely happy or pleased","cn":"非常高兴；欣喜若狂","ex":{"en":"He was overjoyed at my success.","cn":"我的成功使他欣喜若狂。"}}]}},"overdose":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（药物等的）过量；致死（或中毒）剂量","en":"If someone takes an overdose of a drug, they take more of it than is safe.","ex":{"en":"Each year, one in 100 girls aged 15-19 takes an overdose","cn":"每年，每100名15至19岁的少女中就有1位嗑药过量。"}},{"pos":"VERB 动词","cn":"过量服用（药物）；过量吸食（毒品）","en":"If someone overdoses on a drug, they take more of it than is safe.","ex":{"en":"He'd overdosed on heroin","cn":"他曾过量吸食海洛因。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指有害物的）过量，过多","en":"You can refer to too much of something, especially something harmful, as an overdose.","ex":{"en":"An overdose of sun, sea, sand and chlorine can give lighter hair a green tinge.","cn":"过量接触阳光、海水、沙粒和氯气会使浅色头发略呈绿色。"}},{"pos":"VERB 动词","cn":"过多拥有；沉溺","en":"You can say that someone overdoses on something if they have or do too much of it.","ex":{"en":"The city, he concluded, had overdosed on design.","cn":"他的结论是这座城市过分重视规划设计了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to take a dangerously large amount of a drug, usually deliberately","cn":""},{"en":"to take a dangerously large amount of a particular drug, usually by accident","cn":""},{"en":"to take a dangerously large amount of a drug, usually deliberately","cn":""}]},"collocations":{"phrases":["ADJ. large, massive | drug/drugs, heroin, paracetamol, etc. | fatal | accidental","VERB + OVERDOSE take | die from/of","PREP. ~ of She took an overdose of paracetamol."]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdeoverdose.mp3","us":"media/ldoce/hwd/ame/5/overdose.mp3"},"examples":[{"en":"She took a massive overdose of sleeping pills.","cn":"她服用了过量的安眠药。"},{"en":"( figurative ) I had overdosed on sun.","cn":"我晒太阳的时间过长了。"}],"oxford":{"phon":"ˈəʊvədəʊs","pos":"noun","senses":[{"en":"too much of a drug taken at one time, so that it is dangerous","cn":"（一次用药）过量；剂量过大","ex":{"en":"a drug/drugs overdose","cn":"药物剂量过大"}},{"en":"to take too much of a drug at one time, so that it is dangerous","cn":"一次用药过量","lab":"figurative","ex":{"en":"He had overdosed on heroin.","cn":"他过量服用了海洛因。"},"pos":"verb"}]}},"overload":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使超载；使负载过重","en":"If you overload something such as a vehicle, you put more things or people into it than it was designed to carry.","ex":{"en":"Don't overload the boat or it will sink","cn":"别超载，否则船会沉。"}},{"pos":"VERB 动词","cn":"使负担过重；给予…过多的工作（或问题、信息等）","en":"To overload someone with work, problems, or information means to give them more work, problems, or information than they can cope with.","ex":{"en":"...an effective method that will not overload staff with yet more paperwork.","cn":"不会再以更多的文书工作加重员工负荷的有效办法"}},{"pos":"VERB 动词","cn":"使（电力系统）过载；使超过负荷","en":"If you overload an electrical system, you cause too much electricity to flow through it, and so damage it.","ex":{"en":"Never overload an electrical socket.","cn":"千万不要使电源插座过载。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be carrying a lot of things, so that you cannot carry any more","cn":""},{"en":"to be carrying or holding so many things that it is difficult to move or impossible to hold any more","cn":""},{"en":"if someone or something falls or moves unsteadily under the weight of of something, they do this because they are carrying something that is too heavy for them to support","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To overload is to load an excessive amount in or on something, such as an overload of electricity which shorts out the circuits. Overloading causes a \"Too much!\" situation."}]},"collocations":{"phrases":["PREP. with Their staff are heavily overloaded with work.","PHRASES be heavily/seriously overloaded"]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdeoverload.mp3","us":"media/ldoce/hwd/ame/9/overload.mp3"},"examples":[{"en":"In these days of technological change we all suffer from information overload.","cn":"在这科技日新月异的时代，过多的信息使人人都应接不暇。"},{"en":"Don't overload the students with information.","cn":"不要给学生灌输过多的知识。"}],"oxford":{"phon":"ˌəʊvəˈləʊd","pos":"verb","senses":[{"en":"to put too great a load on something","cn":"使超载；使负荷过重","ex":{"en":"an overloaded truck","cn":"一辆超载的卡车"}},{"en":"to give somebody too much of something","cn":"使…负担过重","ex":{"en":"He's overloaded with responsibilities.","cn":"他担负的责任过多。"}},{"en":"to put too great a demand on a computer, an electrical system, etc. causing it to fail","cn":"使（计算机）超载运行；使（电路）超负荷","ex":{"en":"The lights went out because the system was overloaded.","cn":"由于线路过载，电灯灭了。"}},{"en":"too much of something","cn":"过多；过量；超负荷","ex":{"en":"In these days of technological change we all suffer from information overload.","cn":"在这科技日新月异的时代，过多的信息使人人都应接不暇。"},"pos":"noun"}]}},"overcoat":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大衣；厚外套","en":"An overcoat is a thick warm coat that you wear in winter."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long thick warm coat","cn":"大衣"}]},"collocations":{"phrases":["ADJ. long | heavy, thick | dark | tweed •"]},"media":{"uk":"media/ldoce/hwd/bre/3/overcoat0205.mp3","us":"media/ldoce/hwd/ame/a/overcoat.mp3","img":["media/thumb/overcoat.jpg"]},"oxford":{"phon":"ˈəʊvəkəʊt","pos":"noun","senses":[{"en":"a long warm coat worn in cold weather","cn":"长大衣"}]}},"oversee":{"collins":{"senses":[{"pos":"VERB 动词","cn":"监督；监视；监管","en":"If someone in authority oversees a job or an activity, they make sure that it is done properly.","ex":{"en":"Use a surveyor or architect to oversee and inspect the different stages of the work.","cn":"请一位房产检视员或建筑师来监督并检查不同阶段的工作。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if you are in charge of an activity or a group of people, you are the person who has the authority to control what happens, tell other people what to do etc","cn":""},{"en":"to be the person who makes the important decisions about what will happen in a business, organization, country etc","cn":""},{"en":"to be in charge of a business, especially one that is owned by someone else","cn":""}]},"collocations":{"phrases":["ADV. directly | personally He personally oversaw the design of all the rooms.","VERB + OVERSEE be appointed to, be created to, be set up to A committee has been appointed to oversee the work.","PHRASES be responsible for overseeing sth the committee that is responsible for overseeing the day-to-day implementation of this policy"]},"media":{"uk":"media/ldoce/hwd/bre/3/oversee0205.mp3","us":"media/ldoce/hwd/ame/5/oversee.mp3"},"examples":[{"en":"A team leader was appointed to oversee the project.","cn":"任命了一位组长来监管该工程。"}],"oxford":{"phon":"ˌəʊvəˈsiː","pos":"verb","senses":[{"en":"to watch somebody/something and make sure that a job or an activity is done correctly","cn":"监督；监视","ex":{"en":"United Nations observers oversaw the elections.","cn":"联合国观察员监督了选举。"}}]}},"overdraft":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"透支；透支额","en":"If you have an overdraft, you have spent more money than you have in your bank account, and so you are in debt to the bank.","ex":{"en":"When I left Cambridge I had a £10,000 overdraft","cn":"我离开剑桥时，透支了1万英镑。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an amount of money that is borrowed, especially from a bank or company, which you agree to pay back by the end of a period of time","cn":""},{"en":"a large amount of money that someone borrows from a bank or company to buy a house","cn":""},{"en":"money that you pay for borrowing money, especially that you pay every year or every month at a fixed rate","cn":""}]},"collocations":{"phrases":["ADJ. enormous, huge, large | agreed, authorized | unauthorized | free We offer a free &pound; 400 overdraft. | bank","VERB + OVERDRAFT have | get, take out | run up The president ran up a huge overdraft during her year in office. | arrange | extend, give sb,","OVERDRAFT + NOUN facility | limit"]},"media":{"uk":"media/ldoce/hwd/bre/8/overdraft0205.mp3","us":"media/ldoce/hwd/ame/4/overdraft.mp3"},"examples":[{"en":"to run up/pay off an overdraft","cn":"透支；付清透支"},{"en":"Many students have a free overdraft facility (= agreement with their bank to have an overdraft up to a particular limit ) .","cn":"许多学生都能享受免费透支服务。"}],"oxford":{"phon":"ˈəʊvədrɑːft","pos":"noun","senses":[{"en":"the amount of money that you owe to a bank when you have spent more money than is in your bank account; an arrangement that allows you to do this","cn":"透支额；透支安排","lab":"informal","ex":{"en":"She had run up an overdraft of £3 000.","cn":"她已经透支了 3 000 英镑"}}]}},"overlook":{"collins":{"senses":[{"pos":"VERB 动词","cn":"俯瞰；俯视；眺望","en":"If a building or window overlooks a place, you can see the place clearly from the building or window.","ex":{"en":"Pretty and comfortable rooms overlook a flower-filled garden","cn":"漂亮舒适的房间俯视着花团锦簇的花园。"}},{"pos":"VERB 动词","cn":"忽略；忽视；未注意到","en":"If you overlook a fact or problem, you do not notice it, or do not realize how important it is.","ex":{"en":"We overlook all sorts of warning signals about our own health.","cn":"我们忽视有关自身健康的种种预警信号。"}},{"pos":"VERB 动词","cn":"宽容；宽恕","en":"If you overlook someone's faults or bad behaviour, you forgive them and take no action.","ex":{"en":"...satisfying relationships that enable them to overlook each other's faults.","cn":"能使他们互相包容对方缺点的舒心的关系"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to ignore something wrong that someone has done, especially because it is unimportant","cn":""},{"en":"to decide not to punish or criticize someone for doing something wrong, although you might do so if they do it again","cn":""},{"en":"if someone in authority turns a blind eye to illegal activity or bad behaviour, they ignore it and pretend they do not know about it","cn":""}]},"vocab":{"pos":"1 v n 2 v","senses":[{"en":"To overlook something is to fail to see it. When planning a party, it's best to write out a to-do list so that you don't overlook any details."}]},"collocations":{"phrases":["ADV. completely, entirely | largely | frequently, often | generally | conveniently Conveniently overlooking the fact that she wouldn't be ab","VERB + OVERLOOK cannot, cannot afford to, should not We should not overlook this possibility. | be inclined to, tend to Hospitals have tende","PHRASES be easily overlooked another fact which is all too easily overlooked | sth should not be overlooked The importance of this should no"]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdeoverlook.mp3","us":"media/ldoce/hwd/ame/5/overlook.mp3"},"examples":[{"en":"We could not afford to overlook such a serious offence.","cn":"对这样严重的违法行为，我们决不能视若无睹。"},{"en":"Our back yard is overlooked by several houses.","cn":"好几栋房子都看得见我家的后院。"}],"oxford":{"phon":"ˌəʊvəˈlʊk","pos":"verb","senses":[{"en":"to fail to see or notice something","cn":"忽略；未注意到","ex":{"en":"He seems to have overlooked one important fact.","cn":"他好像忽略了一个重要的事实。"}},{"en":"to see something wrong or bad but decide to ignore it","cn":"（对不良现象等）不予理会，视而不见","ex":{"en":"We could not afford to overlook such a serious offence.","cn":"对这样严重的违法行为，我们决不能视若无睹。"}},{"en":"if a building, etc. overlooks a place, you can see that place from the building","cn":"俯视；眺望","ex":{"en":"a restaurant overlooking the lake","cn":"一家濒湖餐厅"}},{"en":"to not consider somebody for a job or position, even though they might be suitable","cn":"（提拔等时）对（某人）不予考虑","ex":{"en":"She's been overlooked for promotion several times.","cn":"几次提职时都没有考虑她。"}}]}},"overestimate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"过高估计（数量、重要性等）","en":"If you say that someone overestimates something, you mean that they think it is greater in amount or importance than it really is.","ex":{"en":"With hindsight, he was overestimating their desire for peace.","cn":"事后看来，他高估了他们对和平的渴望。"}},{"pos":"VERB 动词","cn":"再怎么估量（都不为过）","en":"If you say that something cannot be overestimated, you are emphasizing that you think it is very important.","ex":{"en":"The importance of participating in the life of the country cannot be overestimated","cn":"参与国家生活的重要性再怎么说都不为过。"}},{"pos":"VERB 动词","cn":"过高评价（某人）","en":"If you overestimate someone, you think that they have more of a skill or quality than they really have.","ex":{"en":"I think you overestimate me, Fred.","cn":"我认为你高估我了，弗雷德。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to count something wrongly","cn":""},{"en":"to forget how many things or people you have already counted, when you are counting a lot of things over a long period","cn":""},{"en":"to wrongly guess an amount, price or number by making the total too high","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"If you're confident your favorite team will win the championship even though the star player is injured, you may want to reconsider: don't let your team spirit cause you to overestimate , or overvalue, the team's abilities."}]},"collocations":{"phrases":["ADV. considerably, greatly, grossly, seriously, vastly | consistently The Ministry of Finance consistently overestimated its budget deficits","VERB + OVERESTIMATE tend to | be easy to It is easy to overestimate the cost of this kind of research. | be difficult to, be hard to","PREP. by We overestimated the cost by about 2 per cent.","PHRASES sth cannot be overestimated The importance of this group cannot be overestimated."]},"media":{"uk":"media/ldoce/hwd/bre/0/overestimate_v0205.mp3","us":"media/ldoce/hwd/ame/a/l3overestimate.mp3"},"examples":[{"en":"The importance of these findings cannot be overestimated (= is very great).","cn":"这些发现的重要性是无法充分估量的。"},{"en":"They overestimated his ability when they promoted him.","cn":"他们提拔他的时候高估了他的能力。"}],"oxford":{"phon":"ˌəʊvərˈestɪmeɪt","pos":"verb","senses":[{"en":"to estimate something to be larger, better, more important, etc. than it really is","cn":"高估","ex":{"en":"They overestimated his ability when they promoted him.","cn":"他们提拔他的时候高估了他的能力。"}},{"en":"an estimate about the size, cost, etc. of something that is too high","cn":"过高的评估","ex":{"en":"I thought it would cost about £300, but luckily that turned out to be an overestimate.","cn":"我原以为它会花费大约 300 英镑，但幸运的是，事实证明这个数字被高估了。"},"pos":"noun"}]}},"overwhelm":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（情感、事件等）使不知所措，使难以承受","en":"If you are overwhelmed by a feeling or event, it affects you very strongly, and you do not know how to deal with it.","ex":{"en":"He was overwhelmed by a longing for times past","cn":"他一心渴望回到从前。"}},{"pos":"VERB 动词","cn":"征服；制服；击败","en":"If a group of people overwhelm a place or another group, they gain complete control or victory over them.","ex":{"en":"It was clear that one massive Allied offensive would overwhelm the weakened enemy.","cn":"毫无疑问，盟军一次大规模的进攻就会击溃已是强弩之末的敌军。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to completely defeat an enemy's army because your armed forces are much larger, have better equipment etc","cn":""},{"en":"to completely defeat an enemy's army because your armed forces are much larger, have better equipment etc","cn":""},{"en":"to completely defeat an enemy's army in a war and to destroy all their armed forces","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Overwhelm means “give a person too much of something.” If your friend agrees to feed your pet fish while you’re on vacation, don’t overwhelm her with requests by also asking her to do your laundry and wash the dishes."}]},"collocations":{"phrases":["ADV. completely, totally | almost | suddenly","VERB + OVERWHELM threaten to Deal with stress fast whenever it threatens to overwhelm you.","PREP. with The children pressed around him eagerly, overwhelming him with questions.","PHRASES be/feel overwhelmed (by/with sth) We were totally overwhelmed by the response to our appeal. She felt completely overwhelmed."]},"media":{"uk":"media/ldoce/hwd/bre/e/overwhelm0205.mp3","us":"media/ldoce/hwd/ame/d/overwhelm.mp3"},"examples":[{"en":"The beauty of the landscape overwhelmed me.","cn":"秀丽的风光令我深深地陶醉。"},{"en":"We were overwhelmed by requests for information.","cn":"各方的问讯使我们应接不暇。"}],"oxford":{"phon":"ˌəʊvəˈwelm","pos":"verb","senses":[{"en":"to have such a strong emotional effect on somebody that it is difficult for them to resist or know how to react","cn":"（感情或感觉）充溢，难以承受","ex":{"en":"She was overwhelmed by feelings of guilt.","cn":"她感到愧疚难当。"}},{"en":"to defeat somebody completely","cn":"彻底战胜；击败","ex":{"en":"The army was overwhelmed by the rebels.","cn":"军队被叛乱者完全击败了。"}},{"en":"to be so bad or so great that a person cannot deal with it; to give too much of a thing to a person","cn":"压垮；使应接不暇","ex":{"en":"We were overwhelmed by requests for information.","cn":"各方的问讯使我们应接不暇。"}},{"en":"to cover somebody/something completely","cn":"淹没；漫过","lab":"literary","ex":{"en":"The wave broke through the wall and overwhelmed the town.","cn":"海浪冲破了城墙，淹没了小镇。"}}]}},"overcast":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"多云的；阴沉的；阴天的","en":"If it is overcast, or if the sky or the day is overcast, the sky is completely covered with cloud and there is not much light.","ex":{"en":"For three days it was overcast","cn":"连续3天都是阴天。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"with a lot of clouds","cn":""},{"en":"grey in colour, because there are dark clouds – used especially in written descriptions","cn":""},{"en":"dark and completely covered with clouds","cn":""}]},"collocations":{"phrases":["VERBS be, look | become The sky became heavily overcast. | remain, stay","ADV. heavily, very"]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdeovercast.mp3","us":"media/ldoce/hwd/ame/4/overcast.mp3"},"examples":[{"en":"Today it will be dull and overcast.","cn":"今天天气将阴伴多云。"},{"en":"an overcast sky/day","cn":"阴沉的天空/一天"}],"oxford":{"phon":"ˌəʊvəˈkɑːst","pos":"adjective","senses":[{"en":"covered with clouds; not bright","cn":"阴天的；多云的；阴暗的","ex":{"en":"an overcast sky/day","cn":"阴沉的天空／天气"}}]}},"overhear":{"collins":{"senses":[{"pos":"VERB 动词","cn":"偶然听到；无意中听到；偷听到","en":"If you overhear someone, you hear what they are saying when they are not talking to you and they do not know that you are listening.","ex":{"en":"I overheard two doctors discussing my case.","cn":"我无意中听到两位医生讨论我的病情。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to know that a sound is being made, using your ears","cn":""},{"en":"to pay attention to something, using your ears","cn":""},{"en":"to hear something with difficulty","cn":""}]},"collocations":{"phrases":["ADV. accidentally","PHRASES couldn't help overhearing sth Excuse me for interrupting, but I couldn't help overhearing what you were saying."]},"media":{"uk":"media/ldoce/hwd/bre/5/overhear0205.mp3","us":"media/ldoce/hwd/ame/7/overhear.mp3"},"examples":[{"en":"I overheard a conversation between two boys on the bus.","cn":"我在公共汽车上无意中听到两个男孩的对话。"},{"en":"We talked quietly so as not to be overheard.","cn":"我们低声交谈，以免别人听到。"}],"oxford":{"phon":"ˌəʊvəˈhɪə(r)","pos":"verb","senses":[{"en":"to hear, especially by accident, a conversation in which you are not involved","cn":"偶然听到；无意中听到","ex":{"en":"I overheard a conversation between two boys on the bus.","cn":"我在公共汽车上无意中听到两个男孩的对话。"}}]}}});
